  {
    "stem": "新冠病毒灭活疫苗接种后人体产生特异性免疫应答预防感染。下列关于体液免疫正确的是",
    "options": {"A": "新冠疫苗作为抗原可被浆细胞特异性识别并分泌相应抗体", "B": "B细胞活化需要双信号：抗原直接刺激和辅助性T细胞表面特定分子变化", "C": "浆细胞大量增殖分化为记忆B细胞实现二次免疫快速应答", "D": "接种后产生抗体可直接裂解被新冠病毒感染的体细胞"},
    "answer": "B",
    "analysis": "【A错误：浆细胞是唯一能分泌抗体的细胞，但浆细胞不具有识别抗原功能（无抗原受体）；能识别抗原的是B细胞记忆细胞辅助性T细胞等。】；【B正确：B细胞活化需要双信号：第一信号抗原与B细胞BCR直接结合；第二信号辅助性T细胞表面特定分子（CD40L等）变化并结合，同时辅助性T细胞分泌细胞因子促进B细胞活化增殖分化。】；【C错误：浆细胞高度分化已丧失分裂增殖能力，短时间内分泌大量抗体后凋亡；记忆B细胞由部分活化B细胞增殖分化而来，长期存活二次免疫快速增殖分化为浆细胞。】；【D错误：抗体是蛋白质只能识别结合内环境（细胞外）的游离抗原（病毒颗粒），阻止病毒吸附进入细胞；裂解被病毒感染体细胞是细胞免疫中细胞毒性T细胞功能。】。本题考查免疫系统章节中体液免疫的相关知识点，牢固掌握核心原理即可正确解答。",
    "knowledge": ["高中生物学", "免疫系统", "体液免疫"],
    "module": "module_3",
    "difficulty": "basic",
    "target": "high_school",
    "concept": "免疫系统"
  },
