  {
    "stem": "下列关于人体心脏结构和血液循环路径叙述正确的是",
    "options": {"A": "左心室和右心室之间有房室瓣防止血液倒流", "B": "肺循环路径：右心室→肺动脉→肺部毛细血管→肺静脉→左心房", "C": "动脉中流动都是动脉血静脉中流动都是静脉血", "D": "心脏四个腔中右心室壁最厚收缩时将血液泵向全身"},
    "answer": "B",
    "analysis": "【A错误：心脏左右两侧完全隔开（左右不相通），左心室右心室之间没有直接通道也没有房室瓣；房室瓣位于同侧心房心室之间（左房室瓣二尖瓣、右房室瓣三尖瓣）。】；【B正确：肺循环又称小循环：右心室收缩→肺动脉各级分支→肺部毛细血管网（气体交换静脉血变动脉血）→肺静脉→左心房。】；【C错误：动脉血静脉血根据含氧量多少区分（颜色鲜红暗红），不是根据血管名称；如肺动脉流静脉血（含氧量低），肺静脉流动脉血（含氧量高）。】；【D错误：四个腔壁最厚是左心室，因为左心室将血液泵向全身（体循环）输送距离最长压力最大；右心室只将血液泵向肺部（肺循环）距离短压力小，壁比左心室薄。】。本题考查循环系统章节中心脏血液循环的相关知识点，牢固掌握核心原理即可正确解答。",
    "knowledge": ["高中生物学", "循环系统", "心脏血液循环"],
    "module": "module_3",
    "difficulty": "basic",
    "target": "high_school",
    "concept": "循环系统"
  },
