  {
    "stem": "理想无限环境中某种细菌种群数量每20分钟分裂一次呈J型增长。下列关于种群数量变化叙述正确的是",
    "options": {"A": "J型增长模型Nt=N0λ^t中λ表示该种群出生率", "B": "自然界中绝大多数种群较长时间都呈J型增长", "C": "环境容纳量K值是环境条件不受破坏时一定空间所能维持的种群最大数量", "D": "种群数量达到K值时出生率大于死亡率种群数量继续上升"},
    "answer": "C",
    "analysis": "【A错误：Nt=N0λ^t中λ表示种群数量是一年前数量的倍数（λ>1种群增长）；λ不直接等于出生率，与出生率死亡率都有关。】；【B错误：J型增长是理想条件（食物空间无限气候适宜无天敌）指数增长；自然界资源空间总是有限，存在天敌疾病等，绝大多数种群较长时间呈S型增长（逻辑斯谛增长），J型增长只在理想或初期短暂出现。】；【C正确：环境容纳量又称K值，是环境条件不受破坏时一定空间所能维持的种群最大数量；K值不是固定不变，环境改善K值上升，环境破坏K值下降；种群达到K值时增长停止。】；【D错误：种群数量达到K值时出生率与死亡率基本相等，种群增长速率为0，种群数量在K值附近保持相对稳定不再继续上升；K/2前增长速率最快。】。本题考查种群生态章节中种群数量变化的相关知识点，牢固掌握核心原理即可正确解答。",
    "knowledge": ["高中生物学", "种群生态", "种群数量变化"],
    "module": "module_3",
    "difficulty": "basic",
    "target": "high_school",
    "concept": "种群生态"
  },
